#!/bin/sh
# Starts NeoDesk Quick Support for <base>. Nothing is installed: the
# app runs from a folder in your cache and asks you before anyone sees
# your screen.
set -eu

BASE='<base>'
CODE='{secret:support_code}'

case "$(uname -m)" in
	x86_64 | amd64) arch=x64 ;;
	aarch64 | arm64) arch=arm64 ;;
